  "trigger": "攻击者可控的 Log4j2 配置被加载，其中 JDBC Appender 的 DataSource jndiName 指向恶意 JNDI URI，触发 JNDI 远程类加载执行代码。",
  "preconditions": [
    "攻击者能够修改或控制 Log4j2 配置文件（如 log4j2.xml）",
    "配置中启用 JDBC Appender，且 DataSource 的 jndiName 指向攻击者可控的 JNDI/LDAP URI",
    "Log4j 加载或重新加载该恶意配置",
    "目标可访问攻击者控制的 JNDI/LDAP 服务并允许远程类加载"
  ],
  "exploit_evidence": [
    {
      "src": 0,
      "kind": "poc",
      "quote": "漏洞PoC已在互联网出现。"
    },
    {
      "src": 5,
      "kind": "poc",
      "quote": "This repository contains a working PoC for CVE-2021-44832, a Log4j 2.17.0 RCE vulnerability."
    },
    {
      "src": 4,
      "kind": "poc",
      "quote": "还是使用Github上大佬的环境 https://github.com/tangxiaofeng7/apache-log4j-poc"
    }
  ],
  "fixed_version": "2.17.1",
  "summary_zh": "攻击者若能修改 Log4j2 配置，可用 JDBC Appender 的 JNDI 数据源触发 RCE，请升级至 2.17.1。"
}
